// (harmonic minor) pulls hard back to D minor.
const nightHarmony = { chords: "<Dm Dm Bb Bb Gm Gm A7 A7>", roots: "<d2 d2 bb1 bb1 g1 g1 a1 a1>",
  rootNumbers: "<38 38 34 34 31 31 33 33>" }

